func TestMockedUserPropsRepoScopesCompositeKeys(t *testing.T) {
	repo := &MockedUserPropsRepo{}
	// These pairs collide when joined with an underscore.
	if err := repo.Put("a_b", "c", "first"); err != nil {
		t.Fatal(err)
	}
	if err := repo.Put("a", "b_c", "second"); err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct{ userID, key, want string }{
		{"a_b", "c", "first"},
		{"a", "b_c", "second"},
	} {
		got, err := repo.DefaultGet(tc.userID, tc.key, "default")
		if err != nil || got != tc.want {
			t.Errorf("DefaultGet(%q, %q) = %q, %v; want %q", tc.userID, tc.key, got, err, tc.want)
		}
	}
	if err := repo.Delete("a_b", "c"); err != nil {
		t.Fatal(err)
	}
	if got, err := repo.Get("a", "b_c"); err != nil || got != "second" {
		t.Errorf("deleting another user's property changed this value: got %q, %v", got, err)
	}
	if got, err := repo.DefaultGet("a_b", "c", "default"); err != nil || got != "default" {
		t.Errorf("missing property default = %q, %v; want default", got, err)
	}
}

func TestMockedUserPropsRepoRequiresUserID(t *testing.T) {
	repo := &MockedUserPropsRepo{}
	if err := repo.Put("", "key", "value"); err != model.ErrInvalidAuth {
		t.Errorf("Put without user ID = %v; want ErrInvalidAuth", err)
	}
	if _, err := repo.Get("", "key"); err != model.ErrInvalidAuth {
		t.Errorf("Get without user ID = %v; want ErrInvalidAuth", err)
	}
	if _, err := repo.DefaultGet("", "key", "default"); err != model.ErrInvalidAuth {
		t.Errorf("DefaultGet without user ID = %v; want ErrInvalidAuth", err)
	}
	if err := repo.Delete("", "key"); err != model.ErrInvalidAuth {
		t.Errorf("Delete without user ID = %v; want ErrInvalidAuth", err)
	}
}

